"OLAYLAR_ORTACAG_ORTADOGU:1131-09-14:0":{"b": ["Անժուի կոմս Ֆուլկը և Մելիսենդան Սուրբ Հարության տաճարում թագադրվեցին որպես թագավոր և թագուհի. Բոդուեն II-ի մահով Անժուի հարստությունն անցավ Երուսաղեմի գահին։", "41fc14fc"], "d": ["Անժուի կոմս Ֆուլկը և Մելիսենդան Սուրբ Հարության տաճարում թագադրվեցին որպես թագավոր և թագուհի. Բոդուեն II-ի մահով Անժուի հարստությունն անցավ Երուսաղեմի գահին։", "41fc14fc"]},
"OLAYLAR_ORTACAG_ORTADOGU:1132-01-01:0":{"b": ["Զանգին գրավեց Էրբիլը և տվեց իր հրամանատար Ալի Քյուչուկին", "a31efa5a"], "d": ["Մոսուլի աթաբեկ Իմադ ալ-Դին Զանգին 1132 թ. գրավեց Էրբիլը և տվեց իր հրամանատարներից Զայն ալ-Դին Ալի Քյուչուկին. Բեգթեգինյանների հարստությունը հիմնվեց այնտեղ։", "fd13cba2"]},
"OLAYLAR_ORTACAG_ORTADOGU:1135-01-01:0":{"b": ["Զանգին կրկին վերցրեց Համան", "9831ac12"], "d": ["Բուրիի կողմից վերագրավված Համան Զանգին 1135 թ. կրկին վերցրեց և դարձրեց Միջին Սիրիայի ռազմագործողությունների հենակետ։", "e68193ed"]},
"OLAYLAR_ORTACAG_ORTADOGU:1144-07-04:0":{"b": ["Էրբիլում Զայն ալ-Դին Ալի Քյուչուկը մտնում է տիրակալների ցանկ (Բեգթեգինյաններ)", "7871a2b3"], "d": ["Բեգթեգինյանների (Էրբիլի աթաբեկների) տիրակալների ցանկը Զայն ալ-Դին Ալի Քյուչուկից սկսվում է 539 (1144) թվականով. երբ Զանգին 1144 թ. վերցրեց Ուրֆան, Ալի Քյուչուկին նշանակել էր Ուրֆայի կուսակալ։", "0eba5393"]},
