"OLAYLAR_ORTACAG_ORTADOGU:1174-01-01:1":{"b": ["Թուրան շահի Այյուբյան ուժերը վերցրին Զաբիդը, Մահդի Աբդ ալ-Նաբին և նրա եղբայր Ահմեդը գերի ընկան։", "9fab63aa"], "d": ["Թուրան շահի Այյուբյան ուժերը վերցրին Զաբիդը, Մահդի Աբդ ալ-Նաբին և նրա եղբայր Ահմեդը գերի ընկան։", "9fab63aa"]},
"OLAYLAR_ORTACAG_ORTADOGU:1174-05-15:0":{"b": ["Նուր ալ-Դին Մահմուդը մահացավ Դամասկոսում. Հալեպում գահ բարձրացվեց նրա որդի ալ-Մալիք ալ-Սալիհ Իսմայիլը, սկսվեց Զանգյան ժառանգության բաժանումը։", "763a0e16"], "d": ["Նուր ալ-Դին Մահմուդը մահացավ Դամասկոսում. Հալեպում գահ բարձրացվեց նրա որդի ալ-Մալիք ալ-Սալիհ Իսմայիլը, սկսվեց Զանգյան ժառանգության բաժանումը։", "763a0e16"]},
"OLAYLAR_ORTACAG_ORTADOGU:1175-01-01:0":{"b": ["Թուրան շահը, առաջանալով բարձրավանդակներ, վերցրեց Սանան, Համդանյան սուլթան Ալի բ. Հաթիմը նահանջեց ամրոց։", "595388d0"], "d": ["Թուրան շահը, առաջանալով բարձրավանդակներ, վերցրեց Սանան, Համդանյան սուլթան Ալի բ. Հաթիմը նահանջեց ամրոց։", "595388d0"]},
"OLAYLAR_ORTACAG_ORTADOGU:1175-05-06:0":{"b": ["Սալահ ալ-Դինը Եգիպտոսում հռչակեց անկախություն և ստացավ խալիֆայի հավանությունը. Զանգյան Հալեպի ճյուղի հետ այլևս թշնամական դիրքերում էր (12 Շավվալ 570)։", "44acc78e"], "d": ["Սալահ ալ-Դինը Եգիպտոսում հռչակեց անկախություն և ստացավ խալիֆայի հավանությունը. Զանգյան Հալեպի ճյուղի հետ այլևս թշնամական դիրքերում էր (12 Շավվալ 570)։", "44acc78e"]},
"OLAYLAR_ORTACAG_ORTADOGU:1176-06-25:0":{"b": ["Հաշտություն Սալահ ալ-Դինի և ալ-Սալիհ Իսմայիլի միջև. բացի Հալեպից և մի քանի ամրոցներից, Զանգյան երկիրը մնաց Սալահ ալ-Դինին", "b04b749b"], "d": ["Վերջնական համաձայնություն ձեռք բերվեց (15 Զու-լ-հիջջա 571 / 1176 թ. հունիսի 25). Անատոլիայի սելջուկների և Արթուկյանների նույնպես միացած պայմանագրով ալ-Սալիհ Իսմայիլի ձեռքին մնացին միայն Հալեպը և մի քանի ամրոցներ։", "abd4565f"]},
